(async () => {
  try {
    const tc = window.TuquetCrawler;
    const startTime = Date.now();
    const rawHtml = document.documentElement.outerHTML;
    const crawl = await tc.crawlDocument(document, {
      extractMetadata: true,
      extractMainContent: true,
      toMarkdown: true
    });
    const priceMatch = document.body.innerText.match(/£[0-9.]+/);
    const canonicalDoc = tc.buildCanonicalDocument({
      url: window.location.href,
      title: crawl.metadata?.title || document.title,
      markdown: crawl.markdown || '',
      pageType: crawl.pageType,
      payload: {
        price: priceMatch ? priceMatch[0] : null,
        stock: 'In stock'
      },
      rawMeta: crawl.metadata?.openGraph || {},
      rawHtmlLength: rawHtml.length,
      executionMs: Date.now() - startTime,
      generateChunks: true
    });
    automaNextBlock({
      success: true,
      docId: canonicalDoc.id,
      normalizedUrl: canonicalDoc.identity.normalizedUrl,
      urlHash: canonicalDoc.identity.urlHash,
      contentHash: canonicalDoc.lifecycle.contentHash,
      chunksCount: canonicalDoc.chunks?.length || 0,
      sampleChunk: canonicalDoc.chunks?.[0],
      tokenStats: canonicalDoc.content.tokenSavings
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
